1	/* 评分客户端实现：esp_http_client 手拼 multipart/form-data，流式上传 JPEG，
2	 * cJSON 解析响应。依赖由 main/CMakeLists.txt 的 REISTS 提供（esp_http_client/esp-tls/json）。
3	 */
4	#include <string.h>
5	#include <stdio.h>
6	#include "esp_log.h"
7	#include "esp_heap_caps.h"
8	#include "esp_http_client.h"
9	#include "esp_crt_bundle.h"
10	#include "cJSON.h"
11	#include "score_client.h"
12	
13	#define BOUNDARY   "----SelfieScorerBoundary7d1a2c"
14	#define RESP_MAX   (64 * 1024)   /* LLM 建议模式的响应 JSON 有几 KB，64K 富余 */
15	
16	static const char *TAG = "score";
17	
18	/* 从 cJSON 对象安全取字符串（缺失/类型不符返回 NULL） */
19	static const char *jstr(cJSON *obj, const char *key)
20	{
21	    cJSON *it = cJSON_GetObjectItem(obj, key);
22	    return cJSON_IsString(it) ? it->valuestring : NULL;
23	}
24	
25	/* 从 cJSON 对象安全取数字（缺失返回 fallback） */
26	static double jnum(cJSON *obj, const char *key, double fallback)
27	{
28	    cJSON *it = cJSON_GetObjectItem(obj, key);
29	    return cJSON_IsNumber(it) ? it->valuedouble : fallback;
30	}
31	
32	static int parse_score_json(const char *json, score_result_t *out)
33	{
34	    memset(out, 0, sizeof(*out));
35	    cJSON *root = cJSON_Parse(json);
36	    if (!root) {
37	        return -10;
38	    }
39	    cJSON *t = cJSON_GetObjectItem(root, "total");
40	    if (!cJSON_IsNumber(t)) {
41	        cJSON_Delete(root);
42	        return -11;
43	    }
44	    out->total = (float)t->valuedouble;
45	
46	    const char *g = jstr(root, "grade");
47	    if (g) {
48	        strncpy(out->grade, g, sizeof(out->grade) - 1);
49	    }
50	    cJSON *raw = cJSON_GetObjectItem(root, "raw");
51	    if (raw) {
52	        out->beauty       = (float)jnum(raw, "beauty",       0);
53	        out->aesthetic    = (float)jnum(raw, "aesthetic",    0);
54	        out->exposure     = (float)jnum(raw, "exposure",     0);
55	        out->face_quality = (float)jnum(raw, "face_quality", 0);
56	        out->composition  = (float)jnum(raw, "composition",  0);
57	    }
58	    const char *src = jstr(root, "suggestion_source");
59	    if (src) {
60	        strncpy(out->suggestion_source, src, sizeof(out->suggestion_source) - 1);
61	    }
62	    cJSON *sug = cJSON_GetObjectItem(root, "suggestions");
63	    if (cJSON_IsArray(sug) && cJSON_GetArraySize(sug) > 0) {
64	        cJSON *e0 = cJSON_GetArrayItem(sug, 0);
65	        if (cJSON_IsString(e0)) {
66	            strncpy(out->first_suggestion, e0->valuestring, sizeof(out->first_suggestion) - 1);
67	        }
68	    }
69	    cJSON *cb = cJSON_GetObjectItem(root, "crop_box");
70	    if (cJSON_IsArray(cb) && cJSON_GetArraySize(cb) == 4) {
71	        for (int i = 0; i < 4; i++) {
72	            cJSON *e = cJSON_GetArrayItem(cb, i);
73	            out->crop_box[i] = cJSON_IsNumber(e) ? e->valueint : 0;
74	        }
75	    }
76	    cJSON_Delete(root);
77	    out->ok = true;
78	    return 0;
79	}
