81	int score_client_health(void)
82	{
83	    char url[256];
84	    snprintf(url, sizeof(url), "%s/health", SCORE_SERVER_BASE);
85	    esp_http_client_config_t cfg = {
86	        .url = url,
87	        .timeout_ms = 6000,
88	        .crt_bundle_attach = esp_crt_bundle_attach,
89	        .method = HTTP_METHOD_GET,
90	    };
91	    esp_http_client_handle_t h = esp_http_client_init(&cfg);
92	    if (!h) {
93	        return -1;
94	    }
95	    int ret = -1;
96	    if (esp_http_client_open(h, 0) == ESP_OK) {
97	        esp_http_client_fetch_headers(h);
98	        ret = (esp_http_client_get_status_code(h) == 200) ? 0 : -3;
99	    }
100	    esp_http_client_cleanup(h);
101	    return ret;
102	}
