104	int score_client_post(const uint8_t *jpeg, size_t jpeg_len,
105	                      const char *face_bbox, bool use_llm,
106	                      score_result_t *out)
107	{
108	    /* ---- 拼 multipart 各段 ---- */
109	    char hdr[512];
110	    int hl = snprintf(hdr, sizeof(hdr),
111	        "--" BOUNDARY "\r\n"
112	        "Content-Disposition: form-data; name=\"file\"; filename=\"photo.jpg\"\r\n"
113	        "Content-Type: image/jpeg\r\n\r\n");
114	
115	    char bbox_part[256];
116	    int bl = 0;
117	    if (face_bbox && face_bbox[0]) {
118	        bl = snprintf(bbox_part, sizeof(bbox_part),
119	            "\r\n--" BOUNDARY "\r\n"
120	            "Content-Disposition: form-data; name=\"face_bbox\"\r\n\r\n"
121	            "%s\r\n", face_bbox);
122	    }
123	
124	    char tail[512];
125	    int tl = snprintf(tail, sizeof(tail),
126	        "\r\n--" BOUNDARY "\r\n"
127	        "Content-Disposition: form-data; name=\"use_llm\"\r\n\r\n"
128	        "%s\r\n"
129	        "--" BOUNDARY "\r\n"
130	        "Content-Disposition: form-data; name=\"use_image\"\r\n\r\n"
131	        "true\r\n"
132	        "--" BOUNDARY "--\r\n",
133	        use_llm ? "true" : "false");
134	
135	    if (hl <= 0 || tl <= 0 || bl < 0) {
136	        return -1;
137	    }
138	    const int content_length = hl + (int)jpeg_len + bl + tl;
139	
140	    /* ---- HTTP 客户端 ---- */
141	    char post_url[256];
142	    snprintf(post_url, sizeof(post_url), "%s/score", SCORE_SERVER_BASE);
143	    esp_http_client_config_t cfg = {
144	        .url = post_url,
145	        .timeout_ms = 35000,                    /* LLM 最长约 30s，留余量 */
146	        .crt_bundle_attach = esp_crt_bundle_attach,  /* https 时生效，http 无影响 */
147	        .keep_alive_enable = false,
148	    };
149	    esp_http_client_handle_t h = esp_http_client_init(&cfg);
150	    if (!h) {
151	        ESP_LOGE(TAG, "http 客户端初始化失败（检查 SCORE_URL）");
152	        return -1;
153	    }
154	    char ct[96];
155	    snprintf(ct, sizeof(ct), "multipart/form-data; boundary=%s", BOUNDARY);
156	    esp_http_client_set_method(h, HTTP_METHOD_POST);
157	    esp_http_client_set_header(h, "Content-Type", ct);
158	
159	    int ret = -1;
160	    char *resp = heap_caps_malloc(RESP_MAX, MALLOC_CAP_SPIRAM);
161	    if (!resp) {
162	        goto cleanup;
163	    }
164	
165	    /* ---- 发请求 ---- */
166	    if (esp_http_client_open(h, content_length) != ESP_OK) {
167	        ESP_LOGE(TAG, "连接失败（服务没起/隧道断/WiFi 不通）");
168	        goto cleanup;
169	    }
170	    if (esp_http_client_write(h, hdr, hl) != hl) {
171	        goto cleanup;
172	    }
173	    size_t off = 0;                       /* JPEG 分块流式写 */
174	    while (off < jpeg_len) {
175	        size_t chunk = jpeg_len - off > 32768 ? 32768 : jpeg_len - off;
176	        int w = esp_http_client_write(h, (const char *)jpeg + off, chunk);
177	        if (w <= 0) {
178	            ESP_LOGE(TAG, "上传中断于 %u/%u 字节", (unsigned)off, (unsigned)jpeg_len);
179	            goto cleanup;
180	        }
181	        off += w;
182	    }
183	    if (bl && esp_http_client_write(h, bbox_part, bl) != bl) {
184	        goto cleanup;
185	    }
186	    if (esp_http_client_write(h, tail, tl) != tl) {
187	        goto cleanup;
188	    }
189	    esp_http_client_fetch_headers(h);
190	
191	    /* ---- 读响应 ---- */
192	    int rlen = 0;
193	    while (rlen < RESP_MAX - 1) {
194	        int r = esp_http_client_read(h, resp + rlen, RESP_MAX - 1 - rlen);
195	        if (r <= 0) {
196	            break;
197	        }
198	        rlen += r;
199	    }
200	    resp[rlen] = 0;
201	    int code = esp_http_client_get_status_code(h);
202	    if (code != 200) {
203	        ESP_LOGE(TAG, "HTTP %d: %.120s", code, resp);
204	        ret = -3;
205	        goto cleanup;
206	    }
207	
208	    ret = parse_score_json(resp, out);
209	    if (ret != 0) {
210	        ESP_LOGE(TAG, "JSON 解析失败(%d): %.120s", ret, resp);
211	    }
212	
213	cleanup:
214	    if (resp) {
215	        free(resp);
216	    }
217	    esp_http_client_cleanup(h);
218	    return ret;
219	}
