1	/* 自拍评分硬件客户端主程序（ESP32-S3-EYE）
2	 *
3	 * 流程：LCD 显示启动状态 → 连 WiFi → 初始化摄像头 → 探测评分服务连通性
4	 *       → 就绪，按板载 BOOT/IO0 键拍照。
5	 *       照片 POST 到电脑上的 /score 服务（本地五维评分 + LLM 建议），
6	 *       综合分为五维加权（与大模型无关），结果上 LCD + 串口。
7	 *
8	 * 需要改的配置：
9	 *   - WiFi 热点名/密码：下面 WIFI_SSID / WIFI_PASS
10	 *   - 评分服务地址：score_client.h 里 SCORE_SERVER_BASE（隧道给的公网地址）
11	 *
12	 * 摄像头引脚取自乐鑫 esp-bsp 官方板级定义（esp32_s3_eye.h）：
13	 *   XCLK=15 SCCB_SDA=4 SCCB_SCL=5 D0~D7=11/9/8/10/12/18/17/16
14	 *   VSYNC=6 HREF=7 PCLK=13，XCLK 16MHz
15	 */
16	#include <string.h>
17	#include "freertos/FreeRTOS.h"
18	#include "freertos/task.h"
19	#include "freertos/event_groups.h"
20	#include "esp_log.h"
21	#include "esp_timer.h"
22	#include "esp_wifi.h"
23	#include "esp_event.h"
24	#include "esp_netif.h"
25	#include "esp_netif_ip_addr.h"
26	#include "nvs_flash.h"
27	#include "driver/gpio.h"
28	#include "esp_camera.h"
29	#include "score_client.h"
30	#include "lcd.h"
31	
32	/* ==== WiFi 配置（板子连任意能上公网的 WiFi，如手机热点） ==== */
33	#define WIFI_SSID "your-hotspot-name"
34	#define WIFI_PASS "your-hotspot-password"
35	
36	/* ==== 按键（S3-EYE 板载 BOOT 键 = GPIO0） ==== */
37	#define BTN_GPIO 0
38	
39	/* 评分时是否要大模型建议：true 约 5s；false 秒级（本地规则建议）。
40	 * 先用 false 把链路跑通，再改 true。 */
41	#define USE_LLM true
42	
43	static const char *TAG = "main";
44	
45	static EventGroupHandle_t s_wifi_eg;
46	#define WIFI_CONNECTED_BIT BIT0
47	
48	/* ---------------- WiFi station 样板 ---------------- */
49	static void event_handler(void *arg, esp_event_base_t base, int32_t id, void *data)
50	{
51	    if (base == WIFI_EVENT && id == WIFI_EVENT_STA_START) {
52	        esp_wifi_connect();
53	    } else if (base == WIFI_EVENT && id == WIFI_EVENT_STA_DISCONNECTED) {
54	        ESP_LOGW(TAG, "WiFi 断开，重连中...");
55	        esp_wifi_connect();
56	        xEventGroupClearBits(s_wifi_eg, WIFI_CONNECTED_BIT);
57	    } else if (base == IP_EVENT && id == IP_EVENT_STA_GOT_IP) {
58	        ip_event_got_ip_t *e = (ip_event_got_ip_t *)data;
59	        ESP_LOGI(TAG, "WiFi 已连接，IP: " IPSTR, IP2STR(&e->ip_info.ip));
60	        xEventGroupSetBits(s_wifi_eg, WIFI_CONNECTED_BIT);
61	    }
62	}
63	
64	static void wifi_init_sta(void)
65	{
66	    esp_err_t ret = nvs_flash_init();
67	    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
68	        ESP_ERROR_CHECK(nvs_flash_erase());
69	        ESP_ERROR_CHECK(nvs_flash_init());
70	    }
71	    ESP_ERROR_CHECK(esp_netif_init());
72	    ESP_ERROR_CHECK(esp_event_loop_create_default());
73	    esp_netif_create_default_wifi_sta();
74	
75	    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
76	    ESP_ERROR_CHECK(esp_wifi_init(&cfg));
77	
78	    s_wifi_eg = xEventGroupCreate();
79	    esp_event_handler_instance_register(WIFI_EVENT, ESP_EVENT_ANY_ID, &event_handler, NULL, NULL);
80	    esp_event_handler_instance_register(IP_EVENT, IP_EVENT_STA_GOT_IP, &event_handler, NULL, NULL);
81	
82	    wifi_config_t wc = {
83	        .sta = {
84	            .ssid = WIFI_SSID,
85	            .password = WIFI_PASS,
86	            .threshold.authmode = WIFI_AUTH_WPA2_PSK,
87	        },
88	    };
89	    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
90	    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wc));
91	    ESP_ERROR_CHECK(esp_wifi_start());
92	    ESP_LOGI(TAG, "WiFi 初始化完成，连接中...");
93	}
