96	static esp_err_t camera_init(void)
97	{
98	    camera_config_t cc = {
99	        .pin_pwdn     = -1,
100	        .pin_reset    = -1,
101	        .pin_xclk     = 15,
102	        .pin_sccb_sda = 4,     /* 老版本 esp32-camera 字段名为 pin_sscb_sda */
103	        .pin_sccb_scl = 5,
104	        .pin_d7 = 16, .pin_d6 = 17, .pin_d5 = 18, .pin_d4 = 12,
105	        .pin_d3 = 10, .pin_d2 = 8,  .pin_d1 = 9,  .pin_d0 = 11,
106	        .pin_vsync = 6,
107	        .pin_href   = 7,
108	        .pin_pclk   = 13,
109	        .xclk_freq_hz = 16000000,
110	        .ledc_timer   = LEDC_TIMER_0,
111	        .ledc_channel = LEDC_CHANNEL_0,
112	        .pixel_format = PIXFORMAT_JPEG,
113	        .frame_size   = FRAMESIZE_UXGA,   /* 1600x1200，200 万像素 */
114	        .jpeg_quality = 12,               /* 数值越小质量越高，12 约 200-300KB/张 */
115	        .fb_count     = 2,
116	        .fb_location  = CAMERA_FB_IN_PSRAM,
117	        .grab_mode    = CAMERA_GRAB_LATEST,
118	    };
119	    esp_err_t err = esp_camera_init(&cc);
120	    if (err != ESP_OK) {
121	        ESP_LOGE(TAG, "摄像头初始化失败 0x%x（查排线/PSRAM 配置/引脚版本）", err);
122	    } else {
123	        sensor_t *s = esp_camera_sensor_get();
124	        if (s) {
125	            s->vflip = 1;    /* esp-bsp 定义 BSP_CAMERA_VFLIP=1，与官方一致 */
126	            s->hflip = 0;
127	        }
128	        ESP_LOGI(TAG, "摄像头就绪 UXGA JPEG");
129	    }
130	    return err;
131	}
