133	/* ---------------- 拍照 + 评分 ---------------- */
134	static void take_and_score(void)
135	{
136	    camera_fb_t *fb = esp_camera_fb_get();
137	    if (!fb) {
138	        ESP_LOGE(TAG, "取帧失败");
139	        lcd_status("拍照失败·再按一次");
140	        return;
141	    }
142	    ESP_LOGI(TAG, "拍到 %ux%u JPEG，%u 字节", fb->width, fb->height, (unsigned)fb->len);
143	#if USE_LLM
144	    lcd_status("上传评分中…约5s");
145	#else
146	    lcd_status("上传评分中…");
147	#endif
148	
149	    score_result_t r;
150	    int64_t t0 = esp_timer_get_time();
151	    int rc = score_client_post(fb->buf, fb->len, NULL, USE_LLM, &r);
152	    esp_camera_fb_return(fb);
153	
154	    if (rc != 0) {
155	        ESP_LOGE(TAG, "评分失败 rc=%d（-1 网络 -3 状态码 -10/-11 JSON）", rc);
156	        lcd_status("评分失败·检查服务/隧道");
157	        return;
158	    }
159	    float dt = (esp_timer_get_time() - t0) / 1000000.0f;
160	    lcd_status("完成·按BOOT再拍");
161	    lcd_show_result(&r);
162	    ESP_LOGI(TAG, "==============================");
163	    ESP_LOGI(TAG, " 总分 %.1f / 100（%s）  [%.1fs]", r.total, r.grade, dt);
164	    ESP_LOGI(TAG, " 颜值 %.2f  美学 %.2f  曝光 %.2f  人脸清晰 %.2f  构图 %.2f",
165	             r.beauty, r.aesthetic, r.exposure, r.face_quality, r.composition);
166	    if (r.first_suggestion[0]) {
167	        ESP_LOGI(TAG, " 建议[%s]: %s", r.suggestion_source, r.first_suggestion);
168	    }
169	    if (r.crop_box[2] > 0) {
170	        ESP_LOGI(TAG, " 建议裁剪框: [%d, %d, %d, %d]",
171	                 r.crop_box[0], r.crop_box[1], r.crop_box[2], r.crop_box[3]);
172	    }
173	    ESP_LOGI(TAG, "==============================");
174	}
