176	/* ---------------- 按键轮询（消抖） ---------------- */
177	static void button_task(void *arg)
178	{
179	    gpio_config_t io = {
180	        .pin_bit_mask = 1ULL << BTN_GPIO,
181	        .mode = GPIO_MODE_INPUT,
182	        .pull_up_en = GPIO_PULLUP_ENABLE,
183	        .intr_type = GPIO_INTR_DISABLE,
184	    };
185	    gpio_config(&io);
186	    int last = 1;
187	    while (1) {
188	        int now = gpio_get_level(BTN_GPIO);
189	        if (last == 1 && now == 0) {
190	            vTaskDelay(pdMS_TO_TICKS(30));            /* 消抖 */
191	            if (gpio_get_level(BTN_GPIO) == 0) {
192	                take_and_score();
193	            }
194	        }
195	        last = now;
196	        vTaskDelay(pdMS_TO_TICKS(20));
197	    }
198	}
