200	void app_main(void)
201	{
202	    lcd_init();                          /* 屏失败不阻断，结果仍走串口 */
203	    lcd_status("连接WiFi…");
204	
205	    wifi_init_sta();
206	    xEventGroupWaitBits(s_wifi_eg, WIFI_CONNECTED_BIT, pdFALSE, pdTRUE, portMAX_DELAY);
207	
208	    lcd_status("初始化摄像头…");
209	    ESP_ERROR_CHECK(camera_init());
210	
211	    lcd_status("连接评分服务…");
212	    if (score_client_health() == 0) {
213	        lcd_status("就绪·按BOOT拍照");
214	        ESP_LOGI(TAG, "评分服务连通，等待按键拍照");
215	    } else {
216	        lcd_status("服务不通·查隧道");
217	        ESP_LOGW(TAG, "评分服务不可达（服务没起/隧道断/地址错），仍可按键尝试");
218	    }
219	
220	    xTaskCreate(button_task, "btn", 4096, NULL, 5, NULL);
221	}
